from lib import *
S = SS('j276')
steps = [
    step("状态转换(Hibernate 6.6.4 + PostgreSQL 16):new A 的 contains = false、id = null;persist 之后 contains = true,IDENTITY 主键立刻 INSERT 并拿到 id = 2;对托管对象再次 persist 是无操作(新增 SQL 0 条)。find 后 detach:contains = false;对游离对象 persist 抛 EntityExistsException(detached entity passed to persist),remove 抛 IllegalArgumentException(Removing a detached instance)。remove(托管对象) 之后 contains = false(removed 状态,SQL 还没发);对 removed 对象再次 persist 又回到 managed,既不 DELETE 也不 INSERT(新增 SQL 0 条);对 removed 对象 merge 抛 IllegalArgumentException(deleted instance passed to merge);对 new 对象 remove 没有异常(被忽略);persist(null) 抛 IllegalArgumentException。", t=tl(S(1)), done=lidx(S(1), 'new A:contains = false', 'persist 之后:contains = true', '对托管对象再次 persist'), mark=lidx(S(1), '对游离对象 persist', '对游离对象 remove', 'remove(托管对象) 之后', '对 removed 对象再次 persist', '对 removed 对象 merge', '对 new 对象 remove', 'persist(null)'), kv=KV([['persist(游离对象)', 'EntityExistsException'], ['remove(游离对象) / merge(removed)', 'IllegalArgumentException'], ['persist(removed 对象)', '回到 managed,不发任何 SQL']], ['persist(removed 对象)'])),
    step("回调与 SQL 的时机:IDENTITY(A):persist 时 @PrePersist → 立即 insert → @PostPersist;SEQUENCE(B):persist 时先 select nextval,再 @PrePersist,INSERT 与 @PostPersist 要等到 flush;加载后 @PostLoad;修改并 flush:@PreUpdate → update → @PostUpdate;remove 时立刻 @PreRemove,flush 时 delete → @PostRemove。@PostPersist 的触发时刻取决于主键策略:IDENTITY 在 persist 时,SEQUENCE 在 flush 时。", t=tl(S(2)), done=lidx(S(2), 'persist(new A) —— IDENTITY', 'A(IDENTITY) @PrePersist', 'insert into A', 'A(IDENTITY) @PostPersist'), mark=lidx(S(2), 'select nextval', 'B(SEQUENCE) @PrePersist', 'insert into B', 'B(SEQUENCE) @PostPersist', 'A(IDENTITY) @PostLoad', 'A(IDENTITY) @PreUpdate', 'A(IDENTITY) @PostUpdate', 'A(IDENTITY) @PreRemove', 'delete from A', 'A(IDENTITY) @PostRemove'), kv=KV([['IDENTITY', 'persist:@PrePersist → INSERT → @PostPersist'], ['SEQUENCE', 'persist:nextval → @PrePersist;flush:INSERT → @PostPersist'], ['update / remove', '在 flush 时:Pre → SQL → Post']], ['SEQUENCE'])),
    step("回调里改字段:@PreUpdate 里改的 modified 写进同一条 UPDATE;@PostUpdate 里改的 note 在 UPDATE 之后才改,flush 之后内存里 note = set-in-PostUpdate 而库里还是旧值,实体因此再次变脏,commit 时又发一条 UPDATE,@PostUpdate 又被调用一次(这次改成同样的值,不再变脏)。重新加载之后两个字段都保存了,但 @PostUpdate 的那个靠第二条 UPDATE。", t=tl(S(3)), done=lidx(S(3), 'update C set modified', 'flush 之后内存里'), mark=lidx(S(3), 'commit 时又发出', '重新加载'), kv=KV([['@PreUpdate 里的修改', '写进同一条 UPDATE'], ['@PostUpdate 里的修改', '实体再次变脏,commit 时再发 1 条 UPDATE']], ['@PostUpdate 里的修改'])),
    step("回调里的限制与异常:@PrePersist 里抛 IllegalStateException,persist 抛出该异常,事务 getRollbackOnly = true;之后 commit() 没有抛异常,但同一个事务里更早 persist 的 A(\"keep-me\")最终没有保存(commit 实际是回滚)。@PreUpdate 里用 EntityManager 执行 JPQL(规范不允许):每次查询触发自动 flush,flush 又触发 @PreUpdate,@PreUpdate 被递归进入 478 次,最后 StackOverflowError(被我在回调里捕获),这一次 flush 总共发出 951 条 SQL。没有事务时:persist(IDENTITY 主键的 A)不抛异常(但没有 INSERT),flush() 抛 TransactionRequiredException;SEQUENCE 主键的 B 在 persist 时已经执行了 select nextval。", t=tl(S(4)), done=lidx(S(4), '@PrePersist 里抛 IllegalStateException', '之后 commit()'), mark=lidx(S(4), 'keep-me', '被进入了 478 次', '没有事务时 persist(IDENTITY', 'TransactionRequiredException', 'select nextval'), b=bars([['@PreUpdate 里 JPQL:回调进入次数', 478, '478'], ['这次 flush 发出的 SQL', 951, '951']], 951, done=[0, 1]), kv=KV([['@PrePersist 抛异常', '事务被标记为只能回滚,commit 静默回滚'], ['@PreUpdate 里查询', '递归 flush,478 次进入,951 条 SQL,StackOverflowError'], ['没有事务', 'persist 不报错,flush 抛 TransactionRequiredException']], ['@PreUpdate 里查询'])),
]
A = mkartj('j276', 276, 'Java,JPA,Hibernate,实体生命周期,回调,PostgreSQL,真实验证,动画演示',
    '在 Hibernate 6.6.4 + 真实 PostgreSQL 上实测 JPA 实体生命周期:persist(游离对象)抛 EntityExistsException、对 removed 对象再 persist 回到 managed;@PostPersist 在 IDENTITY 下是 persist 时、在 SEQUENCE 下是 flush 时;@PostUpdate 里的修改要靠第二条 UPDATE 保存;@PreUpdate 里执行查询会递归 flush 478 次、发出 951 条 SQL;@PrePersist 抛异常后 commit 静默回滚。',
    'JPA 的实体有四种状态和七个回调,但它们在什么时候发生、与 SQL 的先后关系、回调里能做什么,规范只给出了概要。这篇用真实的 SQL 日志把每一步量出来,包括几个会让人吃惊的边界。',
    [('478 次 / 951 条', '@PreUpdate 里执行 JPQL 时回调被递归进入的次数 / 这次 flush 发出的 SQL 数(最后 StackOverflowError)'), ('persist 时 vs flush 时', '@PostPersist 的触发时刻:IDENTITY 主键在 persist 时,SEQUENCE 主键在 flush 时'), ('false', '@PrePersist 抛异常之后 commit() 没抛异常,但同一事务里更早 persist 的实体是否被保存')],
    [('状态转换', None), ('回调与 SQL 的时机', None), ('回调里改字段', None), ('限制与异常', None)],
    steps, [ENV_J + '。Hibernate ORM 6.6.4.Final、PostgreSQL JDBC 42.7.4、本机 PostgreSQL 16.15(端口 9501);SQL 来自 hibernate.show_sql;@PreUpdate 递归次数取决于栈深度,几次运行在 477–479 之间', '没有验证:Spring 的 @Transactional 与实体监听器(@EntityListeners)的差别、cascade(PERSIST / REMOVE / MERGE)与 orphanRemoval、@Version 实体的 merge、Hibernate 的 Interceptor / Session 事件监听器、其它 JPA 实现的回调顺序'], 'JPA Entity 生命周期')
